SELECT * FROM (SELECT e.event_id,'W:'||s.warehouse_id case_id,e.activity,e.timestamp FROM (SELECT 'A:'||audit_id||':start' event_id,'Stock Audit Started' activity,started_at timestamp,audit_id source_key FROM warehouse_audit WHERE started_at IS NOT NULL AND (1=1)) e JOIN warehouse_audit s ON s.audit_id=e.source_key WHERE s.warehouse_id IS NOT NULL UNION ALL SELECT e.event_id,'W:'||s.warehouse_id case_id,e.activity,e.timestamp FROM (SELECT 'A:'||audit_id||':complete' event_id,'Stock Audit Completed' activity,completed_at timestamp,audit_id source_key FROM warehouse_audit WHERE completed_at IS NOT NULL AND (1=1)) e JOIN warehouse_audit s ON s.audit_id=e.source_key WHERE s.warehouse_id IS NOT NULL UNION ALL SELECT e.event_id,'W:'||COALESCE(q.warehouse_id,d.warehouse_id) case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':start' event_id,'Putaway Started' activity,started_at timestamp,task_id source_key FROM warehouse_task_history WHERE started_at IS NOT NULL AND (task_code='A')) e JOIN warehouse_task_history s ON s.task_id=e.source_key LEFT JOIN receiving_request q ON q.request_id=s.request_id LEFT JOIN dispatch_order d ON d.dispatch_id=s.dispatch_id WHERE COALESCE(q.warehouse_id,d.warehouse_id) IS NOT NULL UNION ALL SELECT e.event_id,'W:'||COALESCE(q.warehouse_id,d.warehouse_id) case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':complete' event_id,'Putaway Completed' activity,completed_at timestamp,task_id source_key FROM warehouse_task_history WHERE completed_at IS NOT NULL AND (task_code='A')) e JOIN warehouse_task_history s ON s.task_id=e.source_key LEFT JOIN receiving_request q ON q.request_id=s.request_id LEFT JOIN dispatch_order d ON d.dispatch_id=s.dispatch_id WHERE COALESCE(q.warehouse_id,d.warehouse_id) IS NOT NULL UNION ALL SELECT e.event_id,'W:'||COALESCE(q.warehouse_id,d.warehouse_id) case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':start' event_id,'Loading Started' activity,started_at timestamp,handling_id source_key FROM handling_history WHERE started_at IS NOT NULL AND (handling_code='L')) e JOIN handling_history s ON s.handling_id=e.source_key LEFT JOIN receiving_request q ON q.request_id=s.request_id LEFT JOIN dispatch_order d ON d.dispatch_id=s.dispatch_id WHERE COALESCE(q.warehouse_id,d.warehouse_id) IS NOT NULL UNION ALL SELECT e.event_id,'W:'||COALESCE(q.warehouse_id,d.warehouse_id) case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':complete' event_id,'Loading Completed' activity,completed_at timestamp,handling_id source_key FROM handling_history WHERE completed_at IS NOT NULL AND (handling_code='L')) e JOIN handling_history s ON s.handling_id=e.source_key LEFT JOIN receiving_request q ON q.request_id=s.request_id LEFT JOIN dispatch_order d ON d.dispatch_id=s.dispatch_id WHERE COALESCE(q.warehouse_id,d.warehouse_id) IS NOT NULL) ORDER BY case_id,timestamp,event_id;
